import { useMutation, type UseMutationOptions } from "@tanstack/react-query";
import { markReadHandler } from "../handlers/markReadHandler";
import type { ApiError } from "../runtime/client";
import type { UserInboxNotificationEntityType } from "../types/UserInboxNotificationEntityType";

type Data = Awaited<ReturnType<typeof markReadHandler>>;
type Vars = UserInboxNotificationEntityType;

export function useMarkRead(
  options?: Omit<UseMutationOptions<Data, ApiError, Vars>, "mutationFn">,
) {
  return useMutation<Data, ApiError, Vars>({
    mutationFn: (vars) => markReadHandler(vars),
    ...options,
  });
}
